import assert from 'node:assert/strict';
import { GoogleGenAI } from '@google/genai';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.GOOGLE_API_KEY, 'the application receives its own API key');
const ai = new GoogleGenAI({ apiKey: process.env.GOOGLE_API_KEY });
const model = 'gemini-2.5-flash';
const contents = 'Explain the purpose of this customer workflow.';
const expected = '[twin-stub:' + model + '] This is a deterministic stub from the Gemini API twin (no model runs). Your last message: ' + contents;
const response = await ai.models.generateContent({ model, contents });
assert.equal(response.text, expected);
assert.equal(response.candidates[0].finishReason, 'STOP');
assert.ok(response.usageMetadata.promptTokenCount > 0 && response.usageMetadata.candidatesTokenCount > 0);
const stream = await ai.models.generateContentStream({ model, contents });
let text = '', finishReason, usage;
for await (const chunk of stream) {
  text += chunk.text ?? '';
  finishReason = chunk.candidates?.[0]?.finishReason ?? finishReason;
  if (chunk.usageMetadata) usage = chunk.usageMetadata;
}
assert.equal(text, expected);
assert.equal(finishReason, 'STOP');
assert.ok(usage.promptTokenCount > 0 && usage.candidatesTokenCount > 0);
console.log(JSON.stringify({ model, text, finishReason, usage }));
